SELECT json_array_agg(
         json_object('location', PULocationID, 'total_fare', total_fare)
       ) AS location_fares
FROM (
  SELECT PULocationID, SUM(total_amount) AS total_fare
  FROM nyc_taxi_trips
  GROUP BY PULocationID
) AS agg;

SELECT row_number() OVER () AS trip_id,
       ST_AsGeoJSON(
         ST_Buffer(
           ST_Point(-73.9857, 40.7484),
           0.01
         )
       ) AS pickup_buffer_geojson
FROM nyc_taxi_trips
WHERE trip_distance > 10
LIMIT 10;
